from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest

def extract_receipt_fields(payload, config=None):
    config = config or {}
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT", config.get("endpoint"))
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY", config.get("key"))

    if not endpoint or not key:
        raise ValueError("Azure Document Intelligence endpoint and key must be provided")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-receipt", AnalyzeDocumentRequest(bytes_source=payload)
    )
    receipts_result = poller.result()

    extracted_data = {}
    if receipts_result.documents:
        receipt = receipts_result.documents[0]

        merchant_name_field = receipt.fields.get("MerchantName")
        if merchant_name_field:
            extracted_data["merchant"] = merchant_name_field.content

        tax_field = receipt.fields.get("TotalTax")
        if tax_field:
            extracted_data["tax"] = tax_field.content

        total_field = receipt.fields.get("Total")
        if total_field:
            extracted_data["total"] = total_field.content

        items_field = receipt.fields.get("Items")
        if items_field and items_field.kind == "array":
            extracted_data["items"] = []
            for item_entry in items_field.value:
                item_data = {}
                if item_entry.kind == "object":
                    item_fields = item_entry.value

                    description_field = item_fields.get("Description")
                    if description_field:
                        item_data["description"] = description_field.content

                    quantity_field = item_fields.get("Quantity")
                    if quantity_field:
                        item_data["quantity"] = quantity_field.content

                    price_field = item_fields.get("TotalPrice")
                    if price_field:
                        item_data["price"] = price_field.content

                if item_data:
                    extracted_data["items"].append(item_data)

    result = extracted_data
    return result
